import{_ as t,o as a,c as r,ac as i}from"./chunks/framework.B-3EzaJq.js";const h=JSON.parse('{"title":"中国共产党第十三届中央委员会第四次全体会议","description":"","frontmatter":{"prev":{"text":"中国共产党第十三届中央委员会第三次全体会议公报","link":"../3/中国共产党第十三届中央委员会第三次全体会议公报"},"next":{"text":"关于赵紫阳同志在反党反社会主义的动乱中所犯错误的报告——李鹏在党的十三届四中全会上的报告","link":"./关于赵紫阳同志在反党反社会主义的动乱中所犯错误的报告"}},"headers":[],"relativePath":"13/4/index.md","filePath":"13/4/index.md"}'),l={name:"13/4/index.md"};function n(o,e,_,s,d,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="中国共产党第十三届中央委员会第四次全体会议" tabindex="-1">中国共产党第十三届中央委员会第四次全体会议 <a class="header-anchor" href="#中国共产党第十三届中央委员会第四次全体会议" aria-label="Permalink to &quot;中国共产党第十三届中央委员会第四次全体会议&quot;">​</a></h1><p>1989年6月23～24日在北京举行。全会审议并通过了李鹏代表中共中央政治局提出的《关于赵紫阳同志在反党反社会主义的动乱中所犯错误的报告》。会议认为，赵紫阳在关系党和国家生死存亡的关键时刻犯了支持动乱和分裂党的错误，对动乱的形成和发展负有不可推卸的责任，其错误的性质和造成的后果是极为严重的。他在担任党和国家重要领导职务期间，虽然在改革开放和经济工作方面做了一些有益的工作，但是在指导思想上和实际工作中也有明显失误。特别是他主持中央工作以来，消极对待坚持四项基本原则、反对资产阶级自由化的方针，严重忽视党的建设、精神文明建设和思想政治工作，给党的事业造成了严重的损失。鉴于赵紫阳的上述严重错误，全会决定，撤销他的中央委员会总书记、中共中央政治局常务委员会委员、中共中央政治局委员、中央委员会委员和中共中央军事委员会第一副主席的职务。全会对中央领导机构部分成员进行了调整。选举江泽民为中央委员会总书记。</p><ul><li><a href="./关于赵紫阳同志在反党反社会主义的动乱中所犯错误的报告.html">关于赵紫阳同志在反党反社会主义的动乱中所犯错误的报告——李鹏在党的十三届四中全会上的报告</a></li><li><a href="./江泽民在党的十三届四中全会上的讲话.html">江泽民在党的十三届四中全会上的讲话</a></li><li><a href="./中国共产党第十三届中央委员会第四次全体会议公报.html">中国共产党第十三届中央委员会第四次全体会议公报</a></li></ul>',3)])])}const m=t(l,[["render",n]]);export{h as __pageData,m as default};
